import pandas as pd

def client_id_by_card_issue_date(df_card, df_client, df_card_issue_date):
    card_issue_date = df_card_issue_date[df_card_issue_date['issued'] == '1994/3/3']

    if not card_issue_date.empty:
        card_issue_date = card_issue_date.merge(df_card[['card_id']], left_index=True, right_index=True)
        card_issue_date = card_issue_date.merge(df_client[['client_id']], left_index=True, right_index=True)

        return card_issue_date[['client_id']]
    else:
        return pd.DataFrame(columns=['client_id'])
```

```python
import pandas as pd

def get_credit_card_type(client_id, card, client):
    client_card = pd.merge(card, client, on='client_id')
    client_card = client_card[client_card['client_id'] == client_id]
    if client_card.empty:
        return None
    else:
        return client_card['type'].iloc[0]
```

